# Verify hypothesis: if both regions have 9 at same position → output is 3
# otherwise output is 9
import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo2i = G.get('Demo pair 2 input')
demo2o = G.get('Demo pair 2 output')

top = demo2i[:9]
bot = demo2i[10:]

def predict_output(top, bot):
    result = [[9] * len(top[0]) for _ in range(len(top))]
    for ri in range(len(top)):
        for ci in range(len(top[0])):
            if top[ri][ci] == 9 and bot[ri][ci] == 9:
                result[ri][ci] = 3
            else:
                result[ri][ci] = 9
    return result

predicted = predict_output(top, bot)

# Check accuracy
errors = 0
total = 0
for ri in range(9):
    for ci in range(27):
        total += 1
        if predicted[ri][ci] != demo2o[ri][ci]:
            errors += 1

print(f"Hypothesis accuracy on Demo 2: {total - errors}/{total} correct")
if errors > 0:
    print(f"Errors found!")
    for ri in range(9):
        for ci in range(27):
            if predicted[ri][ci] != demo2o[ri][ci]:
                print(f"  ({ri},{ci}): predicted={predicted[ri][ci]}, actual={demo2o[ri][ci]}, top={top[ri][ci]}, bot={bot[ri][ci]}")

